class Solution {
public:
    int minWastedSpace(vector<int>& packages, vector<vector<int>>& boxes) {
        const long long MOD = 1000000007;
        sort(packages.begin(), packages.end());
        int n = packages.size();
        vector<long long> prefix(n + 1, 0);
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + packages[i];

        long long ans = LLONG_MAX;
        for (auto& supplier : boxes) {
            sort(supplier.begin(), supplier.end());
            if (supplier.back() < packages.back()) continue;

            long long total = 0;
            int prev = 0;
            for (int boxSize : supplier) {
                if (prev >= n) break;
                int idx = upper_bound(packages.begin() + prev, packages.end(), boxSize) - packages.begin();
                if (idx > prev) {
                    long long sumRange = prefix[idx] - prefix[prev];
                    total += (long long)(idx - prev) * boxSize - sumRange;
                    prev = idx;
                }
            }
            if (prev == n) ans = min(ans, total);
        }

        if (ans == LLONG_MAX) return -1;
        return (int)(ans % MOD);
    }
};
